-- PostgreSQL 15+; учебная схема Модуля 2
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE project_status AS ENUM ('ACTIVE','SUSPENDED','COMPLETED','TERMINATED_EARLY');
CREATE TYPE approval_status AS ENUM ('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED');
CREATE TYPE deviation_type AS ENUM ('SCHEDULE','BUDGET','KPI','DATA_QUALITY');
CREATE TYPE deviation_status AS ENUM ('OPEN','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TYPE proposal_state AS ENUM ('PENDING','CONFIRMED','REJECTED');
CREATE TYPE sync_status AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED');
CREATE TABLE projects(project_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, enterprise_id TEXT NOT NULL, department_id TEXT, status project_status NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE external_project_ids(external_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects, source_code TEXT NOT NULL, external_project_id TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_code,external_project_id));
CREATE INDEX ix_external_project_ids_project ON external_project_ids(project_id);
CREATE TABLE plan_versions(plan_version_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects, version_number INT NOT NULL CHECK(version_number>0), approval_status approval_status NOT NULL DEFAULT 'DRAFT', planned_start_date DATE NOT NULL, planned_end_date DATE NOT NULL, planned_budget NUMERIC(18,2) NOT NULL CHECK(planned_budget>=0), currency CHAR(3) NOT NULL, approved_at TIMESTAMPTZ, approved_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(project_id,version_number), CHECK(planned_end_date>=planned_start_date), CHECK(approval_status<>'APPROVED' OR approved_at IS NOT NULL));
CREATE TABLE stages(stage_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), plan_version_id UUID NOT NULL REFERENCES plan_versions, external_stage_id TEXT, name TEXT NOT NULL, planned_duration_days INT NOT NULL CHECK(planned_duration_days>0), actual_duration_days INT CHECK(actual_duration_days>=0), actual_start_date DATE, actual_end_date DATE, CHECK(actual_end_date IS NULL OR actual_start_date IS NULL OR actual_end_date>=actual_start_date));
CREATE TABLE kpi_targets(kpi_target_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), plan_version_id UUID NOT NULL REFERENCES plan_versions, code TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL, target_value NUMERIC(20,6) NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('HIGHER_IS_BETTER','LOWER_IS_BETTER')), threshold_percent NUMERIC(8,3) NOT NULL CHECK(threshold_percent>=0), UNIQUE(plan_version_id,code));
CREATE TABLE users(user_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), external_subject TEXT UNIQUE NOT NULL, role TEXT NOT NULL CHECK(role IN ('MINISTRY_EMPLOYEE','DEPARTMENT_MANAGER','ENTERPRISE_REP','RESPONSIBLE_PERSON')), enterprise_id TEXT, department_id TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE user_project_scopes(user_id UUID NOT NULL REFERENCES users, project_id UUID NOT NULL REFERENCES projects, PRIMARY KEY(user_id,project_id));
CREATE TABLE sync_runs(sync_run_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_code TEXT NOT NULL, status sync_status NOT NULL DEFAULT 'QUEUED', attempt_count INT NOT NULL DEFAULT 0 CHECK(attempt_count>=0), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, last_success_at TIMESTAMPTZ, error_code TEXT, error_message TEXT, data_stale BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE source_snapshots(snapshot_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sync_run_id UUID NOT NULL REFERENCES sync_runs, project_id UUID REFERENCES projects, source_code TEXT NOT NULL, source_record_id TEXT NOT NULL, payload JSONB NOT NULL, observed_at TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_code,source_record_id));
CREATE TABLE kpi_actuals(kpi_actual_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects, source_code TEXT NOT NULL, source_record_id TEXT NOT NULL, kpi_code TEXT NOT NULL, actual_value NUMERIC(20,6) NOT NULL, unit TEXT NOT NULL, observed_at TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_code,source_record_id,kpi_code));
CREATE TABLE financial_actuals(financial_actual_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects, source_code TEXT NOT NULL, source_record_id TEXT NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, expense_amount NUMERIC(18,2) NOT NULL CHECK(expense_amount>=0), payment_amount NUMERIC(18,2) NOT NULL CHECK(payment_amount>=0), currency CHAR(3) NOT NULL, observed_at TIMESTAMPTZ NOT NULL, UNIQUE(source_code,source_record_id), CHECK(period_end>=period_start));
CREATE TABLE documents(document_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects, file_name TEXT NOT NULL, storage_key TEXT NOT NULL, content_type TEXT, uploaded_by UUID REFERENCES users, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE status_proposals(proposal_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects, proposed_status project_status NOT NULL, event_code TEXT NOT NULL, reason TEXT NOT NULL, state proposal_state NOT NULL DEFAULT 'PENDING', proposed_by_system TEXT NOT NULL, decided_by UUID REFERENCES users, decision_comment TEXT, supporting_document_id UUID REFERENCES documents, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), decided_at TIMESTAMPTZ, CHECK(state<>'CONFIRMED' OR proposed_status NOT IN ('SUSPENDED','TERMINATED_EARLY') OR (length(trim(reason))>0 AND length(trim(coalesce(decision_comment,'')))>0 AND supporting_document_id IS NOT NULL)));
CREATE TABLE project_status_history(status_history_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects, old_status project_status, new_status project_status NOT NULL, proposal_id UUID REFERENCES status_proposals, changed_by UUID REFERENCES users, reason TEXT NOT NULL, comment TEXT, document_id UUID REFERENCES documents, changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE deviations(deviation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects, type deviation_type NOT NULL, status deviation_status NOT NULL DEFAULT 'OPEN', title TEXT NOT NULL, description TEXT, measured_value NUMERIC(20,6), threshold_value NUMERIC(20,6), assignee_id UUID REFERENCES users, detected_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ, closed_at TIMESTAMPTZ, resolved_by UUID REFERENCES users, closed_by UUID REFERENCES users);
CREATE INDEX ix_deviations_project_status ON deviations(project_id,status);
CREATE TABLE deviation_history(deviation_history_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), deviation_id UUID NOT NULL REFERENCES deviations, old_status deviation_status, new_status deviation_status NOT NULL, actor_id UUID REFERENCES users, comment TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_log(audit_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES users, entity_type TEXT NOT NULL, entity_id UUID NOT NULL, action TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
-- Утверждённые версии защищаются от UPDATE/DELETE в прикладном слое/триггере.
